 if len(prior['inventory'])!=150 or missing[:4]!=CODES or p['selection']!=CODES or sum(r['has_timely_reading_facts']for r in prior['inventory'])!=110:raise ValueError('eighteenth four selection changed')
 fresh=inputs['current_extension']['market_inputs']
